INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h29h-2017-q21','exam-sg','ソーシャルエンジニアリング','standard','single_choice','【2017年度 平成29年春期 午前 問21】ソーシャルエンジニアリングに該当するものはどれか。','[{"id":"a","text":"清掃員を装って廃棄された紙ごみを収集し，企業や組織の重要情報を盗み出す。"},{"id":"b","text":"キーボード入力を記録するソフトウェアをPC上で動作させ，利用者IDやパスワードを窃取する。"},{"id":"c","text":"日本人の名前や日本語の単語を登録した辞書を用いて，プログラムでパスワードを解読する。"},{"id":"d","text":"利用者IDとパスワードの対応リストを用いて，Webサイトへのログインを自動的かつ連続的に試みる。"}]','"a"','正解はア。人を装ったり心理的な隙を突いたりして情報を得る行為がソーシャルエンジニアリングに当たる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q22','exam-sg','電子署名・公開鍵暗号','standard','single_choice','【2017年度 平成29年春期 午前 問22】ディジタル署名に用いる鍵の組合せのうち，適切なものはどれか。','[{"id":"a","text":"作成に用いる鍵：共通鍵／検証に用いる鍵：秘密鍵"},{"id":"b","text":"作成に用いる鍵：公開鍵／検証に用いる鍵：秘密鍵"},{"id":"c","text":"作成に用いる鍵：秘密鍵／検証に用いる鍵：共通鍵"},{"id":"d","text":"作成に用いる鍵：秘密鍵／検証に用いる鍵：公開鍵"}]','"d"','正解はエ。電子署名は署名者の秘密鍵で作成し，対応する公開鍵で検証する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q23','exam-sg','Web攻撃・ディレクトリトラバーサル','standard','single_choice','【2017年度 平成29年春期 午前 問23】ディレクトリトラバーサル攻撃に該当するものはどれか。','[{"id":"a","text":"入力データにデータベース命令を構成する文字列を与え，意図しないSQL文を実行させる。"},{"id":"b","text":"パス名を使ってファイルを指定し，管理者の意図していないファイルを不正に閲覧する。"},{"id":"c","text":"Webアプリケーションの出力エスケープ処理の欠陥を悪用し，ブラウザ上で悪意のあるスクリプトを実行させる。"},{"id":"d","text":"ログイン中の利用者のセッションIDを不正に取得し，その利用者になりすましてサーバにアクセスする。"}]','"b"','正解はイ。ディレクトリトラバーサルはパス指定を悪用して，本来アクセスできないファイルを参照させる攻撃である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q24','exam-sg','情報セキュリティ特性','standard','single_choice','【2017年度 平成29年春期 午前 問24】JIS Q 27000:2014における真正性及び信頼性の定義a～dの組合せのうち，適切なものはどれか。定義a：意図する行動と結果が一貫している特性。b：エンティティが主張どおりのものである特性。c：認可されたエンティティが要求時にアクセス・使用できる特性。d：認可されていない個人等に情報を使用させず，開示しない特性。','[{"id":"a","text":"真正性：a／信頼性：c"},{"id":"b","text":"真正性：b／信頼性：a"},{"id":"c","text":"真正性：b／信頼性：d"},{"id":"d","text":"真正性：d／信頼性：a"}]','"b"','正解はイ。真正性はエンティティが主張どおりであること，信頼性は意図する行動と結果が一貫していることを表す。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q25','exam-sg','電子証明書・CRL','standard','single_choice','【2017年度 平成29年春期 午前 問25】何らかの理由で有効期間中に失効したディジタル証明書の一覧を示すデータはどれか。','[{"id":"a","text":"CA"},{"id":"b","text":"CP"},{"id":"c","text":"CPS"},{"id":"d","text":"CRL"}]','"d"','正解はエ。CRL（証明書失効リスト）は，有効期間中に失効した証明書を一覧にしたものである。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q26','exam-sg','決済セキュリティ・PCI DSS','standard','single_choice','【2017年度 平成29年春期 午前 問26】クレジットカードなどのカード会員データのセキュリティ強化を目的として制定され，技術面及び運用面の要件を定めたものはどれか。','[{"id":"a","text":"ISMS適合性評価制度"},{"id":"b","text":"PCI DSS"},{"id":"c","text":"特定個人情報保護評価"},{"id":"d","text":"プライバシーマーク制度"}]','"b"','正解はイ。PCI DSSはカード会員データを保護するための技術面・運用面のセキュリティ基準である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q27','exam-sg','内部統制・不正のトライアングル','standard','single_choice','【2017年度 平成29年春期 午前 問27】不正のトライアングルを構成する要素の説明として，適切なものはどれか。','[{"id":"a","text":"「機会」とは，技術・物理環境・組織ルールなど，不正行為を可能又は容易にする環境が存在することである。"},{"id":"b","text":"「情報と伝達」とは，必要な情報を識別・処理し，関係者に伝えることである。"},{"id":"c","text":"「正当化」とは，ノルマによるプレッシャーなどのことである。"},{"id":"d","text":"「動機」とは，不正行為を自ら納得させるための責任転嫁などの理由付けである。"}]','"a"','正解はア。不正のトライアングルは動機・機会・正当化で構成され，機会は不正を実行しやすくする環境を指す。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q28','exam-sg','ネットワークセキュリティ・IPsec','standard','single_choice','【2017年度 平成29年春期 午前 問28】OSI基本参照モデルのネットワーク層で動作し，「認証ヘッダ（AH）」と「暗号ペイロード（ESP）」の二つのプロトコルを含むものはどれか。','[{"id":"a","text":"IPsec"},{"id":"b","text":"S/MIME"},{"id":"c","text":"SSH"},{"id":"d","text":"XML暗号"}]','"a"','正解はア。IPsecはネットワーク層でIP通信を保護し，AHとESPを利用する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q29','exam-sg','Webセキュリティ・WAF','standard','single_choice','【2017年度 平成29年春期 午前 問29】WAF（Web Application Firewall）におけるブラックリスト又はホワイトリストの説明として，適切なものはどれか。','[{"id":"a","text":"ブラックリストは脆弱性のあるWebサイトのIPアドレスを登録し，該当通信を遮断する。"},{"id":"b","text":"ブラックリストは問題のある通信データのパターンを定義し，該当通信を遮断又は無害化する。"},{"id":"c","text":"ホワイトリストは暗号化された受信データの復号方法を定義し，復号鍵がないデータを遮断する。"},{"id":"d","text":"ホワイトリストは脆弱性のないWebサイトのFQDNを登録し，登録がないWebサイトへの通信を遮断する。"}]','"b"','正解はイ。ブラックリスト方式では既知の不正な通信パターンを定義し，該当する通信を検出・遮断する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q30','exam-sg','脆弱性診断・ポートスキャン','standard','single_choice','【2017年度 平成29年春期 午前 問30】Webサーバの検査におけるポートスキャナの利用目的はどれか。','[{"id":"a","text":"Webサーバで稼働しているサービスを列挙し，不要なサービスが稼働していないことを確認する。"},{"id":"b","text":"Webサーバの利用者ID管理状況を運用者に確認し，情報セキュリティポリシーからの逸脱を調べる。"},{"id":"c","text":"Webサーバへのアクセス履歴を解析して，不正利用を検出する。"},{"id":"d","text":"正規の利用者IDでログインしてコンテンツを確認し，コンテンツの脆弱性を検出する。"}]','"a"','正解はア。ポートスキャナはサーバで待受けているポートやサービスを調べ，不要な公開サービスを発見するために使う。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja');
